package config

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type File struct {
	Global   map[string]string
	Sections map[string]map[string]string
}

type AnnualEvent struct {
	Category string
	Name     string
	Month    int
	Day      int
}

func Load(path string) (*File, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("Failed to open file: %s", path)
	}
	defer f.Close()

	cfg := &File{
		Global:   map[string]string{},
		Sections: map[string]map[string]string{},
	}

	current := cfg.Global

	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section := strings.TrimSpace(line[1 : len(line)-1])
			if section == "" {
				current = cfg.Global
				continue
			}
			if _, ok := cfg.Sections[section]; !ok {
				cfg.Sections[section] = map[string]string{}
			}
			current = cfg.Sections[section]
			continue
		}

		key, value, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		current[strings.TrimSpace(key)] = strings.TrimSpace(value)
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}

	return cfg, nil
}

func (f *File) GlobalValue(key string) string {
	return f.Global[key]
}

func (f *File) SectionValue(section, key string) string {
	values, ok := f.Sections[section]
	if !ok {
		return ""
	}
	return values[key]
}

func ParseBool(raw string) (bool, bool) {
	if raw == "" {
		return false, false
	}

	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "true", "1", "yes", "on":
		return true, true
	case "false", "0", "no", "off":
		return false, true
	default:
		return false, false
	}
}

func ParseInt(raw string) (int, bool) {
	if raw == "" {
		return 0, false
	}
	value, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil {
		return 0, false
	}
	return value, true
}

func (f *File) RecentEventsWindow() int {
	if section, ok := f.Sections["calendar-events"]; ok {
		if value, found := ParseInt(section["recent-events-window"]); found {
			return value
		}
	}
	return 60
}

func (f *File) AnnualEvents() []AnnualEvent {
	type partial struct {
		name string
		date string
	}

	grouped := map[string]partial{}

	for section, values := range f.Sections {
		if !strings.HasPrefix(section, "calendar-events.") {
			continue
		}
		rest := strings.TrimPrefix(section, "calendar-events.")
		parts := strings.Split(rest, ".")
		if len(parts) < 2 {
			continue
		}
		category := parts[0]
		index := parts[len(parts)-1]
		key := category + "." + index
		grouped[key] = partial{
			name: valueOr(grouped[key].name, values["name"]),
			date: valueOr(grouped[key].date, values["date"]),
		}
	}

	keys := make([]string, 0, len(grouped))
	for key := range grouped {
		keys = append(keys, key)
	}
	sort.Strings(keys)

	events := make([]AnnualEvent, 0, len(keys))
	for _, key := range keys {
		item := grouped[key]
		if item.name == "" || item.date == "" {
			continue
		}
		parts := strings.Split(strings.TrimSuffix(item.date, "."), ".")
		if len(parts) != 2 {
			continue
		}
		day, err1 := strconv.Atoi(parts[0])
		month, err2 := strconv.Atoi(parts[1])
		if err1 != nil || err2 != nil {
			continue
		}
		category, _, _ := strings.Cut(key, ".")
		events = append(events, AnnualEvent{
			Category: category,
			Name:     item.name,
			Month:    month,
			Day:      day,
		})
	}

	return events
}

func valueOr(current, fallback string) string {
	if fallback != "" {
		return fallback
	}
	return current
}

