+	if format == "" {
+		format = DefaultLogNameFormat
+	}
+
+	var pattern strings.Builder
+	pattern.WriteString("^")
+
+	for i := 0; i < len(format); i++ {
+		if format[i] != '%' {
+			pattern.WriteString(regexp.QuoteMeta(string(format[i])))
+			continue
+		}
+
+		if i+1 >= len(format) {
+			pattern.WriteString("%")
