func NewPathCodec(format string) (*PathCodec, error) {
	if format == "" {
		format = DefaultLogNameFormat
	}

	var pattern strings.Builder
	pattern.WriteString("^")

	for i := 0; i < len(format); i++ {
		if format[i] != '%' {
			pattern.WriteString(regexp.QuoteMeta(string(format[i])))
			continue
		}

		if i+1 >= len(format) {
			pattern.WriteString("%")
			continue
		}
		i++

		switch format[i] {
		case '%':
			pattern.WriteString("%")
		case 'Y':
			pattern.WriteString(`(?P<year>\d{4})`)
		case 'y':
			pattern.WriteString(`(?P<year2>\d{2})`)
		case 'm':
			pattern.WriteString(`(?P<month>\d{2})`)
		case 'd':
			pattern.WriteString(`(?P<day>\d{2})`)
		default:
			pattern.WriteString(regexp.QuoteMeta("%" + string(format[i])))
		}
	}

	pattern.WriteString("$")

	re, err := regexp.Compile(pattern.String())
	if err != nil {
		return nil, err
	}

	return &PathCodec{format: format, re: re}, nil
}

