	var out strings.Builder

	for i := 0; i < len(c.format); i++ {
		if c.format[i] != '%' {
			out.WriteByte(c.format[i])
			continue
		}

		if i+1 >= len(c.format) {
			out.WriteByte('%')
			continue
		}
		i++

		switch c.format[i] {
		case '%':
			out.WriteByte('%')
		case 'Y':
			out.WriteString(date.Format("2006"))
		case 'y':
			out.WriteString(date.Format("06"))
		case 'm':
			out.WriteString(date.Format("01"))
		case 'd':
			out.WriteString(date.Format("02"))
		default:
			out.WriteByte('%')
			out.WriteByte(c.format[i])
		}
	}

	return out.String()
}

