	for _, marker := range []string{" (", ":"} {
		if idx := strings.Index(raw, marker); idx >= 0 && idx < cut {
			cut = idx
		}
	}

	return strings.ToLower(strings.TrimSpace(raw[:cut]))
}

func sortCountItems(counts map[string]int) []CountItem {
	items := make([]CountItem, 0, len(counts))
	for name, count := range counts {
		items = append(items, CountItem{Name: name, Count: count})
	}

	sort.Slice(items, func(i, j int) bool {
		return items[i].Name < items[j].Name
	})
	return items
}

func incrementCount(counts map[string]int, key string) {
	counts[key]++
}

func ensureDateSet(target map[string]map[string]struct{}, key, dateKey string) {
	if _, ok := target[key]; !ok {
		target[key] = map[string]struct{}{}
	}
	target[key][dateKey] = struct{}{}
}

func ensureNestedDateSet(target map[string]map[string]map[string]struct{}, section, tag, dateKey string) {
	if _, ok := target[section]; !ok {
		target[section] = map[string]map[string]struct{}{}
	}
	if _, ok := target[section][tag]; !ok {
		target[section][tag] = map[string]struct{}{}
	}
	target[section][tag][dateKey] = struct{}{}
}

func cloneSet(in map[string]struct{}) map[string]struct{} {
	out := map[string]struct{}{}
	for key := range in {
		out[key] = struct{}{}
	}
	return out
}

func removeEmptyParents(dir, stop string) error {
	stop = filepath.Clean(stop)
	current := filepath.Clean(dir)

	for strings.HasPrefix(current, stop) && current != stop {
		entries, err := os.ReadDir(current)
		if err != nil {
			return nil
		}
		if len(entries) > 0 {
			return nil
		}
		if err := os.Remove(current); err != nil {
			return nil
		}
		current = filepath.Dir(current)
	}

	return nil
}

