package term

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

type State struct {
	fd   int
	term syscall.Termios
	raw  bool
}

type Winsize struct {
	Rows uint16
	Cols uint16
	X    uint16
	Y    uint16
}

func MakeRaw() (*State, error) {
	fd := int(os.Stdin.Fd())

	termios, err := getTermios(fd)
	if err != nil {
		return nil, err
	}

	raw := *termios
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0

	if err := setTermios(fd, &raw); err != nil {
		return nil, err
	}

	return &State{fd: fd, term: *termios, raw: true}, nil
}

func (s *State) Restore() error {
	if s == nil || !s.raw {
		return nil
	}
	if err := setTermios(s.fd, &s.term); err != nil {
		return err
	}
	s.raw = false
	return nil
}

func GetWinsize() (Winsize, error) {
	ws := Winsize{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return Winsize{}, errno
	}
	return ws, nil
}

func EnterAltScreen() {
	fmt.Fprint(os.Stdout, "\x1b[?1049h\x1b[?25l")
}

func LeaveAltScreen() {
	fmt.Fprint(os.Stdout, "\x1b[?25h\x1b[?1049l")
}

func ClearScreen() {
	fmt.Fprint(os.Stdout, "\x1b[2J\x1b[H")
}

func getTermios(fd int) (*syscall.Termios, error) {
	termios := &syscall.Termios{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(termios)))
	if errno != 0 {
		return nil, errno
	}
	return termios, nil
}

func setTermios(fd int, termios *syscall.Termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(termios)))
	if errno != 0 {
		return errno
	}
	return nil
}

