package tui

import (
	"fmt"
	"strings"
)

type Style struct {
	Fg        int
	Bold      bool
	Dim       bool
	Underline bool
	Inverse   bool
}

type Cell struct {
	Ch    rune
	Style Style
}

type Canvas struct {
	Width  int
	Height int
	Cells  [][]Cell
}

func NewCanvas(width, height int) *Canvas {
	cells := make([][]Cell, height)
	for y := range cells {
		cells[y] = make([]Cell, width)
		for x := range cells[y] {
			cells[y][x] = Cell{Ch: ' '}
		}
	}
	return &Canvas{Width: width, Height: height, Cells: cells}
}

func (c *Canvas) Set(x, y int, ch rune, style Style) {
	if x < 0 || y < 0 || x >= c.Width || y >= c.Height {
		return
	}
	c.Cells[y][x] = Cell{Ch: ch, Style: style}
}

func (c *Canvas) DrawText(x, y int, text string, style Style) {
	if y < 0 || y >= c.Height {
		return
	}
	col := x
	for _, ch := range text {
		if col >= c.Width {
			break
		}
		if col >= 0 {
			c.Set(col, y, ch, style)
		}
		col++
	}
}

func (c *Canvas) DrawTextClipped(x, y, width int, text string, style Style) {
	c.DrawText(x, y, fitString(text, width), style)
}

func (c *Canvas) DrawCentered(y int, text string, style Style) {
	c.DrawText((c.Width-runeLen(text))/2, y, text, style)
}

func (c *Canvas) DrawBox(x, y, width, height int, title string, style Style) {
	if width < 2 || height < 2 {
		return
	}

	leftTop := '\u256d'
	rightTop := '\u256e'
	leftBottom := '\u2570'
	rightBottom := '\u256f'
	hLine := '\u2500'
	vLine := '\u2502'

	c.Set(x, y, leftTop, style)
	c.Set(x+width-1, y, rightTop, style)
	c.Set(x, y+height-1, leftBottom, style)
	c.Set(x+width-1, y+height-1, rightBottom, style)

	for col := x + 1; col < x+width-1; col++ {
		c.Set(col, y, hLine, style)
		c.Set(col, y+height-1, hLine, style)
	}
	for row := y + 1; row < y+height-1; row++ {
		c.Set(x, row, vLine, style)
		c.Set(x+width-1, row, vLine, style)
	}

	if title != "" && width > 4 {
		label := fitString(title, width-2)
		c.DrawText(x+1, y, label, style)
	}
}

func (c *Canvas) FillRect(x, y, width, height int, ch rune, style Style) {
	for row := 0; row < height; row++ {
		for col := 0; col < width; col++ {
			c.Set(x+col, y+row, ch, style)
		}
	}
}

func (c *Canvas) DimAll() {
	for y := 0; y < c.Height; y++ {
		for x := 0; x < c.Width; x++ {
			cell := c.Cells[y][x]
			cell.Style.Dim = true
			c.Cells[y][x] = cell
		}
	}
}

func (c *Canvas) Render() string {
	var out strings.Builder
	out.WriteString("\x1b[H")

	current := Style{Fg: -1}
	for y := 0; y < c.Height; y++ {
		for x := 0; x < c.Width; x++ {
			cell := c.Cells[y][x]
			if cell.Style != current {
				out.WriteString(styleANSI(cell.Style))
				current = cell.Style
			}
			out.WriteRune(cell.Ch)
		}
		out.WriteString("\x1b[0m")
		current = Style{Fg: -1}
		if y != c.Height-1 {
			out.WriteString("\r\n")
		}
	}
	return out.String()
}

func styleANSI(style Style) string {
	codes := []string{"0"}
	if style.Bold {
		codes = append(codes, "1")
	}
	if style.Dim {
		codes = append(codes, "2")
	}
	if style.Underline {
		codes = append(codes, "4")
	}
	if style.Inverse {
		codes = append(codes, "7")
	}
	if style.Fg >= 0 {
		codes = append(codes, fmt.Sprintf("%d", style.Fg))
	}
	return "\x1b[" + strings.Join(codes, ";") + "m"
}

func fitString(text string, width int) string {
	if width <= 0 {
		return ""
	}
	runes := []rune(text)
	if len(runes) <= width {
		return text + strings.Repeat(" ", width-len(runes))
	}
	return string(runes[:width])
}

func runeLen(text string) int {
	return len([]rune(text))
}

