package tui

import (
	"io"
)

type Key int

const (
	KeyUnknown Key = iota
	KeyCtrlC
	KeyTab
	KeyShiftTab
	KeyEnter
	KeyBackspace
	KeyUp
	KeyDown
	KeyLeft
	KeyRight
	KeyRune
)

type KeyEvent struct {
	Key  Key
	Rune rune
}

type KeyReader struct {
	r     io.Reader
	queue []KeyEvent
}

func NewKeyReader(r io.Reader) *KeyReader {
	return &KeyReader{r: r}
}

func (k *KeyReader) ReadKey() (KeyEvent, error) {
	if len(k.queue) > 0 {
		event := k.queue[0]
		k.queue = k.queue[1:]
		return event, nil
	}

	buf := make([]byte, 32)
	n, err := k.r.Read(buf)
	if err != nil {
		return KeyEvent{}, err
	}
	if n == 0 {
		return KeyEvent{Key: KeyUnknown}, nil
	}

	k.queue = parseKeys(buf[:n])
	if len(k.queue) == 0 {
		return KeyEvent{Key: KeyUnknown}, nil
	}

	event := k.queue[0]
	k.queue = k.queue[1:]
	return event, nil
}

func parseKeys(data []byte) []KeyEvent {
	events := make([]KeyEvent, 0, len(data))
	for i := 0; i < len(data); i++ {
		switch data[i] {
		case 3:
			events = append(events, KeyEvent{Key: KeyCtrlC})
		case 9:
			events = append(events, KeyEvent{Key: KeyTab})
		case 10, 13:
			events = append(events, KeyEvent{Key: KeyEnter})
		case 127, 8:
			events = append(events, KeyEvent{Key: KeyBackspace})
		case 27:
			if i+1 < len(data) && data[i+1] == '[' {
				if i+2 < len(data) {
					switch data[i+2] {
					case 'A':
						events = append(events, KeyEvent{Key: KeyUp})
						i += 2
						continue
					case 'B':
						events = append(events, KeyEvent{Key: KeyDown})
						i += 2
						continue
					case 'C':
						events = append(events, KeyEvent{Key: KeyRight})
						i += 2
						continue
					case 'D':
						events = append(events, KeyEvent{Key: KeyLeft})
						i += 2
						continue
					case 'Z':
						events = append(events, KeyEvent{Key: KeyShiftTab})
						i += 2
						continue
					}
				}
			}
			events = append(events, KeyEvent{Key: KeyUnknown})
		default:
			if data[i] >= 32 && data[i] <= 126 {
				events = append(events, KeyEvent{Key: KeyRune, Rune: rune(data[i])})
			} else {
				events = append(events, KeyEvent{Key: KeyUnknown})
			}
		}
	}
	return events
}

