+			return
+		}
+		if scratchpad := a.currentScratchpad(); scratchpad != nil {
+			a.openPathInEditor(scratchpad.Path, false)
+			a.refreshScratchpads()
+		}
+	case KeyRune:
+		switch event.Rune {
+		case 'q':
+			a.quit = true
+		case 's':
+			a.view = ViewMain
+			a.focus = FocusSections
+		case 'j':
+			if a.scratchIndex < len(a.scratchpads) {
+				a.scratchIndex++
+			}
+		case 'k':
+			if a.scratchIndex > 0 {
+				a.scratchIndex--
+			}
+		}
+	}
+}
+
+func (a *App) handleScratchInputKey(event KeyEvent) {
+	switch event.Key {
+	case KeyBackspace:
+		if len(a.scratchInput) > 0 {
+			a.scratchInput = a.scratchInput[:len(a.scratchInput)-1]
+		}
+	case KeyEnter:
+		name := strings.TrimSpace(a.scratchInput)
+		a.scratchInputModal = false
+		if name == "" {
+			a.scratchInput = ""
+			return
+		}
+		path := a.scratchpadPath(name)
+		if _, err := os.Stat(path); os.IsNotExist(err) {
+			_ = os.MkdirAll(filepath.Dir(path), 0o755)
+			_ = os.WriteFile(path, []byte{}, 0o644)
+		}
+		a.openPathInEditor(path, false)
+		a.scratchInput = ""
+		a.refreshScratchpads()
+	case KeyRune:
+		a.scratchInput += string(event.Rune)
+	}
+}
+
+func (a *App) navigateUp() {
+	switch a.focus {
+	case FocusSections:
+		if a.sectionIndex > 0 {
+			a.sectionIndex--
+			a.tagIndex = 0
+		}
+	case FocusTags:
+		if a.tagIndex > 0 {
+			a.tagIndex--
+		}
+	case FocusCalendar:
+		a.moveDate(-7)
+	}
+}
+
+func (a *App) navigateDown() {
+	switch a.focus {
+	case FocusSections:
+		if a.sectionIndex < len(a.index.OrderedSections) {
+			a.sectionIndex++
+			a.tagIndex = 0
+		}
+	case FocusTags:
+		if a.tagIndex < len(a.index.TagsForSection(a.selectedSection())) {
+			a.tagIndex++
+		}
+	case FocusCalendar:
+		a.moveDate(7)
+	}
+}
+
+func (a *App) navigateLeft() {
+	switch a.focus {
+	case FocusSections:
+		a.focus = FocusCalendar
+	case FocusTags:
+		a.focus = FocusSections
+	case FocusCalendar:
+		a.moveDate(-1)
+	}
+}
+
+func (a *App) navigateRight() {
+	switch a.focus {
+	case FocusSections:
+		a.focus = FocusTags
+	case FocusTags:
+		a.focus = FocusCalendar
+	case FocusCalendar:
+		a.moveDate(1)
+	}
+}
+
+func (a *App) moveDate(days int) {
+	a.selectedDate = normalizeDate(a.selectedDate.AddDate(0, 0, days))
+	if a.selectedDate.Year() != a.displayYear {
+		a.displayYear = a.selectedDate.Year()
+		_ = a.refreshIndex()
+	}
+}
+
+func (a *App) changeYear(delta int) {
+	newYear := a.displayYear + delta
+	a.displayYear = newYear
+	a.selectedDate = clampDate(newYear, a.selectedDate.Month(), a.selectedDate.Day())
+	_ = a.refreshIndex()
+}
+
+func (a *App) openSelectedLog() {
+	path, _, err := journal.EnsureLog(a.settings.LogDirPath, a.codec, a.selectedDate)
+	if err != nil {
+		return
+	}
+	a.openPathInEditor(path, true)
+}
+
+func (a *App) openPathInEditor(path string, refreshIndex bool) {
+	_ = a.termState.Restore()
+	term.LeaveAltScreen()
+
+	editor := os.Getenv("EDITOR")
+	if strings.TrimSpace(editor) == "" {
+		editor = "vi"
+	}
+
+	command := exec.Command("sh", "-c", editor+" "+shellQuote(path))
+	command.Stdin = os.Stdin
+	command.Stdout = os.Stdout
+	command.Stderr = os.Stderr
+	_ = command.Run()
+
+	state, err := term.MakeRaw()
+	if err == nil {
+		a.termState = state
+	}
+	term.EnterAltScreen()
+
+	if refreshIndex {
+		_ = a.refreshIndex()
+	}
+}
+
+func (a *App) draw() {
+	ws, err := term.GetWinsize()
+	width := 80
+	height := 24
+	if err == nil {
+		width = int(ws.Cols)
+		height = int(ws.Rows)
+	}
+	if width < 40 {
+		width = 40
+	}
+	if height < 12 {
+		height = 12
+	}
+
+	canvas := NewCanvas(width, height)
+	if a.view == ViewScratch {
+		a.drawScratchView(canvas)
+	} else {
+		a.drawMainView(canvas)
+	}
+
+	switch {
+	case a.passwordModal:
+		canvas.DimAll()
+		a.drawInputModal(canvas, "Enter password for log files:", maskString(a.passwordInput))
+	case a.deleteModal:
+		canvas.DimAll()
+		a.drawDeleteModal(canvas)
+	case a.scratchInputModal:
+		canvas.DimAll()
+		a.drawInputModal(canvas, "Enter the name of the scratchpad to open:", a.scratchInput)
+	}
+
+	fmt.Fprint(os.Stdout, canvas.Render())
+}
+
+func (a *App) drawMainView(canvas *Canvas) {
+	header := fmt.Sprintf("Today is: %s.  | There are %d log entries for year %d.",
+		a.today.Format("02. 01. 2006"), a.index.LogCount, a.displayYear)
+	canvas.DrawCentered(0, header, Style{Bold: true, Underline: true})
+
+	sectionsWidth := min(21, max(18, canvas.Width/4))
+	tagsWidth := min(20, max(18, canvas.Width/5))
+	calendarX := sectionsWidth + tagsWidth + 2
+	calendarWidth := max(20, canvas.Width-calendarX)
+	previewHeight := min(5, canvas.Height-2)
+	if previewHeight < 5 {
+		previewHeight = 5
+	}
+	menusHeight := max(6, canvas.Height-previewHeight-1)
+
+	a.drawListBox(canvas, 0, 1, sectionsWidth, menusHeight, "Sections", a.sectionRows(), a.sectionIndex, a.focus == FocusSections)
+	a.drawListBox(canvas, sectionsWidth+1, 1, tagsWidth, menusHeight, "Tags", a.tagRows(), a.tagIndex, a.focus == FocusTags)
+	a.drawCalendar(canvas, calendarX, 1, calendarWidth, canvas.Height-previewHeight-1, a.focus == FocusCalendar)
+	a.drawPreview(canvas, 0, canvas.Height-previewHeight, canvas.Width, previewHeight)
+}
+
+func (a *App) drawScratchView(canvas *Canvas) {
+	canvas.DrawCentered(0, "Scratchpad Manager", Style{Bold: true})
+	canvas.DrawText(0, 1, strings.Repeat("\u2500", canvas.Width), Style{})
+
+	leftWidth := min(30, max(24, canvas.Width/3))
+	rightWidth := canvas.Width - leftWidth - 1
+	boxY := 2
+	boxHeight := canvas.Height - boxY
+
+	a.drawListBox(canvas, 0, boxY, leftWidth, boxHeight, "Scratchpads", a.scratchRows(), a.scratchIndex, a.focus == FocusScratchpads)
+
+	title := "Select a scratchpad"
+	content := "No scratchpad selected"
+	if scratch := a.currentScratchpad(); scratch != nil {
+		title = scratch.Name
+		content = scratch.Content
+	}
+	canvas.DrawBox(leftWidth+1, boxY, rightWidth, boxHeight, "", Style{Dim: false})
+	canvas.DrawCentered(boxY, title, Style{Underline: true, Dim: true, Bold: true})
+	lines := strings.Split(content, "\n")
+	for i := 0; i < boxHeight-2 && i < len(lines); i++ {
+		canvas.DrawTextClipped(leftWidth+2, boxY+1+i, rightWidth-2, lines[i], markdownStyle(lines[i]))
+	}
+}
+
+func (a *App) drawListBox(canvas *Canvas, x, y, width, height int, title string, rows []string, selected int, focused bool) {
+	style := Style{}
+	if !focused {
+		style.Dim = true
+	}
+	canvas.DrawBox(x, y, width, height, title, style)
+
+	for i := 0; i < height-2 && i < len(rows); i++ {
+		rowStyle := style
+		if i == selected {
+			rowStyle = Style{Bold: true, Inverse: true}
+			if !focused {
+				rowStyle.Dim = true
+			}
+		}
+		canvas.DrawTextClipped(x+1, y+1+i, width-2, rows[i], rowStyle)
+	}
+}
+
+func (a *App) drawCalendar(canvas *Canvas, x, y, width, _ int, focused bool) {
+	colWidth := max(18, width/2)
+	rowHeight := 8
+	matchDates := a.index.MatchingDates(a.selectedSection(), a.selectedTag())
+
+	for month := 1; month <= 12; month++ {
+		row := (month - 1) / 2
+		col := (month - 1) % 2
+		bx := x + col*colWidth
+		bw := colWidth
+		if col == 1 {
+			bw = width - colWidth
+		}
+		by := y + row*rowHeight
+		a.drawMonth(canvas, bx, by, bw, rowHeight, time.Month(month), focused, matchDates)
+	}
+}
+
+func (a *App) drawMonth(canvas *Canvas, x, y, width, height int, month time.Month, focused bool, matches map[string]struct{}) {
+	if width < 12 || height < 4 {
+		return
+	}
+
+	boxStyle := Style{}
+	if !focused {
+		boxStyle.Dim = true
+	}
+
+	title := month.String()
+	if month == time.January {
+		title = fmt.Sprintf("%d", a.displayYear)
+	}
+	canvas.DrawBox(x, y, width, height, title, boxStyle)
+
+	weekdays := []string{"M", "T", "W", "T", "F", "S", "S"}
+	if a.settings.SundayStart {
+		weekdays = []string{"S", "M", "T", "W", "T", "F", "S"}
+	}
+
+	for i, day := range weekdays {
+		canvas.DrawText(x+1+i*3, y+1, day, Style{Underline: true, Dim: boxStyle.Dim})
+	}
+
+	first := time.Date(a.displayYear, month, 1, 0, 0, 0, 0, time.Local)
+	offset := weekdayOffset(first.Weekday(), a.settings.SundayStart)
+	daysInMonth := daysIn(month, a.displayYear)
+
+	row := 0
+	col := offset
+	for day := 1; day <= daysInMonth; day++ {
+		date := time.Date(a.displayYear, month, day, 0, 0, 0, 0, time.Local)
+		key := journal.DateKey(date)
+
+		style := Style{Dim: boxStyle.Dim}
+		if isWeekend(date.Weekday(), a.settings.SundayStart) {
+			style.Fg = 34
+		}
+		if _, ok := matches[key]; ok {
+			style.Bold = true
+			style.Fg = 32
+		}
+		if a.hasEvent(date) {
+			style.Fg = 32
+			style.Underline = true
+		}
+		if sameDate(date, a.today) {
+			style.Fg = 31
+		}
+		if sameDate(date, a.selectedDate) {
+			style.Inverse = true
+			style.Underline = true
+			style.Bold = true
+		}
+
+		canvas.DrawText(x+1+col*3, y+2+row, fmt.Sprintf("%2d", day), style)
+		col++
+		if col > 6 {
+			col = 0
+			row++
+		}
+	}
+}
+
+func (a *App) drawPreview(canvas *Canvas, x, y, width, height int) {
+	title := "log preview"
+	content := ""
+	if a.authenticated {
+		title = fmt.Sprintf("log preview for %s.", a.selectedDate.Format("02. 01. 06"))
+		content = a.index.PreviewForDate(a.selectedDate)
+	}
+
+	canvas.DrawBox(x, y, width, height, "", Style{Dim: true})
+	canvas.DrawCentered(y, title, Style{Underline: true, Bold: true, Dim: true})
+
+	lines := strings.Split(content, "\n")
+	for i := 0; i < height-2 && i < len(lines); i++ {
+		canvas.DrawTextClipped(x+1, y+1+i, width-2, lines[i], markdownStyle(lines[i]))
+	}
+}
+
+func (a *App) drawDeleteModal(canvas *Canvas) {
+	width := min(canvas.Width-4, 43)
+	height := 7
+	x := (canvas.Width - width) / 2
+	y := max(2, (canvas.Height-height)/2)
+
+	canvas.DrawBox(x, y, width, height, "", Style{})
+	canvas.DrawCentered(y+1, "Are you sure you want to delete a log file?", Style{})
+
+	yesStyle := Style{}
+	noStyle := Style{}
+	if a.deleteYes {
+		yesStyle = Style{Bold: true, Inverse: true}
+	} else {
+		noStyle = Style{Bold: true, Inverse: true}
+	}
+
+	canvas.DrawText(x+width/2-8, y+3, " Yes ", yesStyle)
+	canvas.DrawText(x+width/2+2, y+3, " No ", noStyle)
+}
+
+func (a *App) drawInputModal(canvas *Canvas, prompt, value string) {
+	width := min(canvas.Width-4, max(31, runeLen(prompt)+4))
+	height := 7
+	x := (canvas.Width - width) / 2
+	y := max(2, (canvas.Height-height)/2)
+
+	canvas.DrawBox(x, y, width, height, "", Style{})
+	canvas.DrawCentered(y+1, prompt, Style{})
+	canvas.DrawBox(x+2, y+2, width-4, 3, "", Style{})
+	canvas.DrawTextClipped(x+3, y+3, width-6, value, Style{Bold: true, Inverse: true, Fg: 97})
+	canvas.DrawText(x+width/2-3, y+5, "Submit", Style{})
+}
+
+func (a *App) sectionRows() []string {
+	rows := []string{"<select none>"}
+	for _, item := range a.index.OrderedSections {
+		rows = append(rows, fmt.Sprintf("%4d \u2502 %-10s", item.Count, item.Name))
+	}
+	return rows
+}
+
+func (a *App) tagRows() []string {
+	rows := []string{"<select none>"}
+	for _, item := range a.index.TagsForSection(a.selectedSection()) {
+		rows = append(rows, fmt.Sprintf("%4d \u2502 %-10s", item.Count, item.Name))
+	}
+	return rows
+}
+
+func (a *App) scratchRows() []string {
+	rows := []string{"Make new scratchpad"}
+	for _, item := range a.scratchpads {
+		rows = append(rows, item.Name)
+	}
+	return rows
+}
+
+func (a *App) selectedSection() string {
+	if a.sectionIndex == 0 || a.sectionIndex > len(a.index.OrderedSections) {
+		return ""
+	}
+	return a.index.OrderedSections[a.sectionIndex-1].Name
+}
+
+func (a *App) currentScratchpad() *Scratchpad {
+	if a.scratchIndex == 0 {
+		return nil
+	}
+	index := a.scratchIndex - 1
+	if index < 0 || index >= len(a.scratchpads) {
+		return nil
+	}
+	return &a.scratchpads[index]
+}
+
+func (a *App) clampIndexes() {
+	if a.index == nil {
+		a.index = emptyYearIndex(a.displayYear)
+	}
+	if a.sectionIndex > len(a.index.OrderedSections) {
+		a.sectionIndex = len(a.index.OrderedSections)
+	}
+	tagItems := a.index.TagsForSection(a.selectedSection())
+	if a.tagIndex > len(tagItems) {
+		a.tagIndex = len(tagItems)
+	}
+}
+
+func (a *App) hasEvent(date time.Time) bool {
+	for _, event := range a.settings.AnnualEvents {
+		if int(date.Month()) == event.Month && date.Day() == event.Day {
+			return true
+		}
+	}
+	return false
+}
+
+func (a *App) scratchpadDir() string {
+	return filepath.Join(filepath.Dir(a.settings.LogDirPath), "scratchpad")
+}
+
+func (a *App) scratchpadPath(name string) string {
+	filename := name
+	if filepath.Ext(filename) == "" {
+		filename += ".md"
+	}
+	return filepath.Join(a.scratchpadDir(), filename)
+}
+
+func emptyYearIndex(year int) *journal.YearIndex {
+	return &journal.YearIndex{
+		Year:           year,
+		Logs:           map[string]*journal.LogInfo{},
+		SectionCounts:  map[string]int{},
+		TagCounts:      map[string]int{},
+		TagsBySection:  map[string]map[string]int{},
+		DatesBySection: map[string]map[string]struct{}{},
+		DatesByTag:     map[string]map[string]struct{}{},
+		DatesBySectTag: map[string]map[string]map[string]struct{}{},
+	}
+}
+
+func markdownStyle(line string) Style {
+	switch {
+	case strings.HasPrefix(line, "#"):
+		return Style{Bold: true, Fg: 33, Dim: true}
+	case strings.HasPrefix(line, "* "):
+		return Style{Bold: true, Fg: 34}
+	default:
+		return Style{Dim: true}
+	}
+}
+
+func normalizeDate(t time.Time) time.Time {
+	return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.Local)
+}
+
+func clampDate(year int, month time.Month, day int) time.Time {
+	last := daysIn(month, year)
+	if day > last {
+		day = last
+	}
+	return time.Date(year, month, day, 0, 0, 0, 0, time.Local)
+}
+
+func sameDate(a, b time.Time) bool {
+	return a.Year() == b.Year() && a.Month() == b.Month() && a.Day() == b.Day()
+}
+
+func daysIn(month time.Month, year int) int {
+	return time.Date(year, month+1, 0, 0, 0, 0, 0, time.Local).Day()
+}
+
+func weekdayOffset(day time.Weekday, sundayStart bool) int {
+	if sundayStart {
+		return int(day)
+	}
+	if day == time.Sunday {
+		return 6
+	}
+	return int(day) - 1
+}
+
+func isWeekend(day time.Weekday, sundayStart bool) bool {
+	if sundayStart {
+		return day == time.Saturday || day == time.Sunday
+	}
+	return day == time.Saturday || day == time.Sunday
+}
+
+func maskString(text string) string {
+	return strings.Repeat(" ", len(text))
+}
+
+func shellQuote(text string) string {
+	return "'" + strings.ReplaceAll(text, "'", `'\''`) + "'"
+}
+
+func min(a, b int) int {
+	if a < b {
+		return a
+	}
+	return b
+}
+
+func max(a, b int) int {
+	if a > b {
+		return a
+	}
+	return b
+}
